{"operation":"run_python","code":"def nCr(n, r):
    if r < 0 or r > n:
        return 0
    import math
    return math.comb(n, r)

solutions = []
for n in range(1, 100):
    for k in range(n-2):
        c1 = nCr(n, k)
        c2 = nCr(n, k+1)
        c3 = nCr(n, k+2)
        if c1 > 0 and c2 > 0 and c3 > 0:
            if c2 == 2 * c1 and c3 == 3 * c2:
                solutions.append((n, k))

print(solutions)
